package edu.klh.soa.recall; import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.kafka.core.KafkaTemplate;
import java.util.Map;import org.springframework.http.*;import java.time.Instant;import java.util.*;
@RestController @RequestMapping("/recall") public class RecallController {private final RecallRepository repo;private final KafkaTemplate<String, Map<String, Object>> kafka;public RecallController(RecallRepository r,KafkaTemplate<String,Map<String,Object>> k){repo=r;kafka=k;}record Request(String lotCode,String productCode,String reason){} @PostMapping public ResponseEntity<Map<String,Object>> recall(@RequestBody Request r,@RequestHeader(value="X-Correlation-Id",required=false) String correlation){if(r.lotCode()==null||r.productCode()==null||r.reason()==null||r.reason().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"lotCode, productCode and reason required");Instant now=Instant.now();String id=UUID.randomUUID().toString();String corr=correlation==null?UUID.randomUUID().toString():correlation;Map<String,Object> e=new LinkedHashMap<>();e.put("eventId",id);e.put("aggregateId",r.lotCode());e.put("schemaVersion",1);e.put("occurredAt",now.toString());e.put("correlationId",corr);e.put("lotCode",r.lotCode());e.put("productCode",r.productCode());e.put("reason",r.reason());repo.save(new RecallRecord(id,r.lotCode(),r.productCode(),r.reason(),now));kafka.send("soa.s02.t17.events",r.lotCode(),e);return ResponseEntity.accepted().body(Map.of("eventId",id,"status","PUBLISHED","correlationId",corr));} @GetMapping public List<RecallRecord> all(){return repo.findAll();}}